const preferences = {
  region: {
    country: 'Saudi Arabia',
    preferredCities: ['Riyadh','Jeddah','Dammam','Khobar','Al Khobar','Dhahran','Makkah','Madinah','NEOM','Tabuk'],
    includeRemoteWorldwide: true,
    includeHybrid: true,
    includeOnSite: true
  },
  jobTitles: ['Software Engineer','AI Engineer','Machine Learning Engineer','Backend Engineer','Full Stack Engineer','Mobile Developer','iOS Developer','AI Automation Engineer','Python Developer','LLM Engineer','Prompt Engineer','Software Developer'],
  scheduling: { maxJobAgeDays: Number($env.JOB_MAX_AGE_DAYS || 7) },
  scoring: { minMatchScore: Number($env.MIN_MATCH_SCORE || 70) }
};

const sources = {
  adzuna: { enabled: true, searchQueries: ['software engineer','AI engineer','machine learning','backend engineer','python developer','LLM engineer'] },
  greenhouse: { enabled: true, boards: ['neom','careem','hungerstation','tamara','stripe','figma','notion','linear'] },
  lever: { enabled: true, companies: ['noon','spotify','netflix','plaid'] },
  ashby: { enabled: true, jobBoards: ['anthropic','openai','ramp','deel'] },
  rss: { enabled: true, feeds: [
    { name: 'RemoteOK', url: 'https://remoteok.com/remote-dev-jobs.rss' },
    { name: 'WWR Programming', url: 'https://weworkremotely.com/categories/remote-programming-jobs.rss' }
  ]}
};

const settings = {
  notificationEmail: $env.NOTIFICATION_EMAIL,
  autoApplyEnabled: ($env.AUTO_APPLY_ENABLED || 'false').toLowerCase() === 'true',
  minMatchScore: Number($env.MIN_MATCH_SCORE || 70),
  masterResume: $env.MASTER_RESUME_TEXT || 'Replace MASTER_RESUME_TEXT env var or connect Google Drive node.'
};

return [{ json: { preferences, sources, settings, runAt: new Date().toISOString() } }];

const config = $('Load Config').first().json;
const rows = $('Load Processed Job IDs').all().map(r => r.json);
const existingIds = new Set(rows.map(r => r.id).filter(Boolean));

return [{ json: { ...config, existingIds: [...existingIds] } }];

const ctx = $('Merge Config + History').first().json;
const fetched = $('Fetch All Jobs').first().json;
const jobs = fetched.jobs || [];
const prefs = ctx.preferences;
const existing = new Set(ctx.existingIds || []);

const SAUDI = ['riyadh','jeddah','dammam','khobar','dhahran','makkah','madinah','neom','tabuk','saudi','ksa'];
const titles = (prefs.jobTitles||[]).map(t=>t.toLowerCase());
const maxAge = prefs.scheduling?.maxJobAgeDays ?? 7;
const cutoff = new Date(); cutoff.setDate(cutoff.getDate()-maxAge);

function withinDays(d){ if(!d) return true; const p=new Date(d); return !Number.isNaN(p) && p>=cutoff; }

const seen = new Set();
const filtered = [];
for (const job of jobs) {
  if (existing.has(job.id) || seen.has(job.id)) continue;
  seen.add(job.id);
  if (!withinDays(job.datePosted)) continue;
  const titleOk = titles.some(t => job.title.toLowerCase().includes(t));
  if (!titleOk) continue;
  const loc = job.location.toLowerCase();
  const geoOk = job.isSaudi || job.isRemote || SAUDI.some(c=>loc.includes(c));
  if (!geoOk) continue;
  filtered.push(job);
}

return filtered.map(j => ({ json: { job: j, masterResume: ctx.settings.masterResume, minMatchScore: ctx.settings.minMatchScore, autoApplyEnabled: ctx.settings.autoApplyEnabled } }));

const results = $input.all().map(i => i.json);
const qualified = results.filter(r => r.tier === 'qualified').sort((a,b) => (b.matchScore||0)-(a.matchScore||0));
const lowMatch = results.filter(r => r.tier === 'low_match').sort((a,b) => (b.matchScore||0)-(a.matchScore||0));
const all = [...qualified, ...lowMatch];

return [{ json: {
  qualified,
  lowMatch,
  all,
  stats: {
    total: all.length,
    qualified: qualified.length,
    lowMatch: lowMatch.length
  },
  reportDate: new Date().toLocaleDateString('en-SA', { timeZone: 'Asia/Riyadh', weekday:'long', year:'numeric', month:'long', day:'numeric' })
}}];

const data = $input.first().json;
const { qualified, lowMatch, stats, reportDate } = data;

function section(job) {
  const cls = (job.matchScore||0) >= 70 ? 'score' : 'score low';
  return `<div class=\"job\"><span class=\"${cls}\">${job.matchScore||0}% Match</span><div class=\"company\">${job.job.company}</div><div class=\"title\">${job.job.title}</div><div class=\"meta\">${job.job.location} · ${job.job.workType} · ${job.job.source}</div><div class=\"summary\">${job.matchSummary||''}</div><a class=\"btn\" href=\"${job.job.applyUrl}\">View & Apply</a></div>`;
}

const jobSections = [...qualified, ...lowMatch].map(section).join('');

const html = `<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><style>body{font-family:-apple-system,sans-serif;background:#f4f4f5;margin:0;padding:24px}.container{max-width:680px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden}.header{background:#0f172a;color:#fff;padding:24px 28px}.stats{display:flex;gap:16px;padding:16px 28px;background:#f8fafc}.stat{flex:1;text-align:center}.num{font-size:24px;font-weight:700}.label{font-size:12px;color:#64748b}.job{padding:20px 28px;border-bottom:1px solid #e2e8f0}.score{display:inline-block;background:#dcfce7;color:#166534;font-weight:700;padding:2px 10px;border-radius:999px;font-size:13px}.score.low{background:#fef3c7;color:#92400e}.company{font-size:12px;color:#64748b;text-transform:uppercase}.title{font-size:17px;font-weight:600;margin:4px 0}.meta{font-size:13px;color:#475569;margin-bottom:8px}.summary{font-size:14px;color:#334155;line-height:1.5}.btn{display:inline-block;margin-top:10px;background:#2563eb;color:#fff!important;text-decoration:none;padding:8px 16px;border-radius:8px;font-size:13px;font-weight:600}</style></head><body><div class=\"container\"><div class=\"header\"><h1>JobPilot AI — Daily Report</h1><p>${reportDate} · Saudi Arabia & Remote</p></div><div class=\"stats\"><div class=\"stat\"><div class=\"num\">${stats.total}</div><div class=\"label\">Jobs Found</div></div><div class=\"stat\"><div class=\"num\">${stats.qualified}</div><div class=\"label\">Score ≥ 70</div></div><div class=\"stat\"><div class=\"num\">${stats.lowMatch}</div><div class=\"label\">Low Match</div></div></div>${jobSections || '<div class=\"job\">No new jobs today.</div>'}</div></body></html>`;

return [{ json: { ...data, emailHtml: html, emailSubject: `JobPilot Daily — ${stats.qualified} qualified · ${stats.total} total` } }];

const data = $('Build Daily Email').first().json;
const rows = data.all.map(r => ({
  id: r.job.id,
  company: r.job.company,
  title: r.job.title,
  location: r.job.location,
  matchScore: r.matchScore,
  source: r.job.source,
  applyUrl: r.job.applyUrl,
  datePosted: r.job.datePosted,
  processedAt: r.processedAt,
  applicationStatus: r.applicationStatus,
  resumeVersion: r.resumeVersion || '',
  tier: r.tier
}));
return rows.map(r => ({ json: r }));
